window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":109,"source":"خطبه 109 .docx","mode":"explicit-parts","parts":["خطبه ۱۰۹\nبخش اول \nمتن:\nقُدرة اللّه‏:\nكُلُّ شَيْ‏ءٍ خَاشِعٌ لَهُ وَ كُلُّ شَيْ‏ءٍ قَائِمٌ بِهِ، غِنَى كُلِّ فَقِيرٍ وَ عِزُّ كُلِّ ذَلِيلٍ وَ قُوَّةُ كُلِّ ضَعِيفٍ وَ مَفْزَعُ كُلِّ مَلْهُوفٍ، مَنْ تَكَلَّمَ سَمِعَ نُطْقَهُ وَ مَنْ سَكَتَ عَلِمَ سِرَّهُ وَ مَنْ عَاشَ فَعَلَيْهِ رِزْقُهُ وَ مَنْ مَاتَ فَإِلَيْهِ مُنْقَلَبُهُ. لَمْ تَرَكَ الْعُيُونُ فَتُخْبِرَ عَنْكَ بَلْ كُنْتَ قَبْلَ الْوَاصِفِينَ مِنْ خَلْقِكَ، لَمْ تَخْلُقِ الْخَلْقَ لِوَحْشَةٍ وَ لَا اسْتَعْمَلْتَهُمْ لِمَنْفَعَةٍ، وَ لَا يَسْبِقُكَ مَنْ طَلَبْتَ وَ لَا يُفْلِتُكَ مَنْ أَخَذْتَ، وَ لَا يَنْقُصُ سُلْطَانَكَ مَنْ عَصَاكَ وَ لَا يَزِيدُ فِي مُلْكِكَ مَنْ أَطَاعَكَ، وَ لَا يَرُدُّ أَمْرَكَ مَنْ سَخِطَ قَضَاءَكَ وَ لَا يَسْتَغْنِي عَنْكَ مَنْ تَوَلَّى عَنْ أَمْرِكَ. كُلُّ سِرٍّ عِنْدَكَ عَلَانِيَةٌ وَ كُلُّ غَيْبٍ عِنْدَكَ شَهَادَةٌ. أَنْتَ الْأَبَدُ فَلَا أَمَدَ لَكَ وَ أَنْتَ الْمُنْتَهَى فَلَا مَحِيصَ عَنْكَ وَ أَنْتَ الْمَوْعِدُ فَلَا [مُنْجِيَ‏] مَنْجَى مِنْكَ إِلَّا إِلَيْكَ. بِيَدِكَ نَاصِيَةُ كُلِّ دَابَّةٍ وَ إِلَيْكَ مَصِيرُ كُلِّ نَسَمَةٍ. سُبْحَانَكَ مَا أَعْظَمَ شَأْنَكَ، سُبْحَانَكَ مَا أَعْظَمَ مَا نَرَى مِنْ خَلْقِكَ وَ مَا أَصْغَرَ كُلَّ عَظِيمَةٍ فِي جَنْبِ قُدْرَتِكَ، وَ مَا أَهْوَلَ مَا نَرَى مِنْ‏ مَلَكُوتِكَ وَ مَا أَحْقَرَ ذَلِكَ فِيمَا غَابَ عَنَّا مِنْ سُلْطَانِكَ، وَ مَا أَسْبَغَ نِعَمَكَ فِي الدُّنْيَا وَ مَا أَصْغَرَهَا فِي نِعَمِ الْآخِرَةِ.\nترجمه:\nهمه چيز در برابر او خاضع است، و هر چيزى به وجود او قائم مى باشد! بى نياز کننده هر فقير، و عزّت بخش هر خوار و ذليل، و نيروى هر ناتوان، و پناهگاه هر مصيبت رسيده است. هر کس سخن بگويد نطق او را مى شنود، هر کس سکوت کند اسرار درونش را مى داند، آن کس که زنده است روزيش بر اوست، و آن کس که مى ميرد بازگشتش به سوى اوست.\n(پروردگارا!) چشم ها تو را نديده تا از تو خبر دهند; بلکه تو پيش از آنکه وصف کنندگانت وجود پيدا کنند، بوده اى. آفريدگان را براى رفع وحشت تنهايى نيافريدى، و براى سود خود آنها را به کارى وا نداشتى، هيچ کس نمى تواند از پنجه قدرتت بگريزد، و آن کس را که بگيرى از حيطه قدرت تو بيرون نمى رود. معصيت گنهکاران از عظمت تو نمى کاهد و اطاعت مطيعان بر حاکميت تو نمى افزايد. آن کس که از قضا و قَدَر تو به خشم آيد، نمى تواند حکم و فرمانت را دگرگون سازد، و آن کس که از اوامر تو روى گرداند، از تو بى نياز نمى شود. هر رازى نزد تو آشکار، و هر پنهانى پيش تو حاضر است. تو وجودى جاودانى هستى که زمان برايت نيست، تو پايانى هستى که جز بازگشت به سويت راهى وجود ندارد، و وعده گاهى که نجات از حُکمت جز به وسيله تو ممکن نيست. ناصيه (و زمام اختيار) هر جنبنده اى به دست توست، و بازگشت همه نفوس به سوى تو مى باشد.\n(پروردگارا!) پاک و منزّهى! چه بزرگ است مقام تو. (بازهم) منزّهى! چه بزرگ است آنچه را که از آفريده هايت مى بينيم و چه کوچک است هر بزرگى در برابر قدرت و عظمت تو، و چه باشکوه است آنچه را از ملکوتت مشاهده مى کنيم. (با اين حال، چقدر ناچيز است آنچه را مى بينيم، در برابر آنچه از قلمرو حکومتت از ما پنهان است! چه قدر نعمت هاى دنيايت فراوان و پراهميّت است و چه کوچک است اين نعمت ها در برابر نعمت هاى آخرتت.\nتفسیر:\nمعروف به خطبه الزهرا\n(خطبه درخشان و بسیار نورانی)\nابن ابی‌الحدید می‌گوید:\n«اگر کسی می‌خواهد از فصاحت و بلاغت سر درآورد و بداند که از همین حروف الفبا می‌توان کلمات و جملات عجیب ساخت، این خطبه را بخواند و ببیند. غیر از کلام خدا و پیامبر؛ این خطبه؛ هرچه سخنران و ادیب و شاعر گفته‌اند در مقابل کلام علی علیه‌السلام مثل سنگ‌ریزه سیاه و بی‌ارزشی در مقابل ستاره نورانی آسمان است. اگر یک نفر زندیق و کافر مصمم باشد که مرگ و نشور و قیامتی در کار نیست؛ این جملات را بخواند، به هم می‌ریزد و تمام اعتقاداتش منهدم شده و به زلزله می‌افتد».\nمحوریت خطبه در مورد قیامت است.\nکلُّ شَیْءٍ خَاضِعٌ لَهُ\nهمه عالم در مقابل خدا خاشع و خاضع‌اند.\nخشوع و خضوع معانی قریب دارند؛ ولی خشوع معنای گسترده‌تری دارد. خاضع یعنی انسان فروتن و سربه‌زیر باشد؛ ولی خاشع در ظاهر و باطن، در خلوت و در مجالس فروتن است.\nدر عرب کلمه عام‌تری نداریم وقتی با کل هم همراه شود، عجیب محوریت را عام می‌کند. کل شیء یعنی همه‌کس همه چیز همه موجودات عالم حتی سنگی که فهم و شعور ندارد، همه در مقابل خدا خاشع‌اند.\nدر مقابل قوانین عالم، سنت و نکوی الهی کسی نمی‌تواند سرپیچی کند. آسمان‌ها و زمین و انسان‌ها حتی ملحدترین شخص، مجبور است به قوانین آفرینش خاضع باشد. کسی نمی‌تواند در مقابل مرگ و حیات خود مقاومت و تمرد کند. این‌ها قوانین عالم هستند و نمی‌توان از آن‌ها سرپیچی کرد.\nحتی انسان گناهکار که از قانون شرع سرباز می‌زند نمی‌تواند از قوانین کلی الهی سرپیچی کند. آسمان هم باید قانون‌مداریا باشد انسان هم (جدا از بحث شرعیات و انجام عبادات و…) در برابر قانون آفرینش خاشع است.\nوَکُلُّ شَیْءٍ قَائِمٌ بِهِ\nاقتدار و سرپا ایستادن همه عالم به خداست. خدای متعال واجب‌الوجود است و تمام عالم ممکن‌الوجود، یعنی تمام پیامبران، فرشتگان، اجنه، انسان‌های خوب و… قیام همه عالم به خداست. مانوری از پرتو وجود اوییم. در بحث کلام عرض شده که ممکن‌الوجودها هیچ حقیقت و تشخص و استقلالی از خود ندارند مثل نور خورشید که یک شیء خارجی و جدا از خورشید نیست.\nغیر خدا هیچ نیست و هرچه هست مخلوق و قائم به خداست.\nوَغِنَی کلِّ فَقِیرٍ\nبی‌نیازکننده هر فقیری است.\nحضرت در باب توحید عمیق‌ترین مباحث توحیدی را بیان می‌کند. در قرآن کریم فرموده: «أنتم الفقراء إلی الله والله هو الغنی الحمید»\nثروتمندترین شما در مقابل خدا فقر ذاتی دارد؛ یعنی در حقیقت وجودی خود محتاجید. خدای یک‌لحظه فیض خود را از شما بردارد، عدم و نیست می‌شوید نه اینکه بمیرید. مانند قطع‌کردن برق یک لامپ است. حقیقت و باطن همه عالم محتاج به خداوند متعال هستند.\nوَعِزُّ کلِّ ذَلِیلٍ\nخداوند عزت هر ذلیلی است.\nعزت خدا ذاتی است و ذلت ما هم ذاتی است و تنها کسی که می‌تواند به عزت برسد باید باخدا مأنوس باشد و از او عزت بگیرد.\nوَقُوَّةُ کلِّ ضَعِیفٍ\nصفت پنجم خداوند، قوت هر ضعیفی است.\nهمه انسان‌ها و تمام عالم ضعیف هستند و نقص دارند تنها قدرت مطلق و بدون هیچ ضعف و کاستی در بارگاه خدای متعال است و شما می‌توانید از خدا طلب قدرت و عزت و غنا کنید.\nوَمَفْزَعُ کلِّ مَلِیحُوفٍ\nخداوند ملجأ و پناهگاه کسی است که چیزی ازدست‌داده.\nانسان داغ‌دیده که عزیزی ازدست‌داده و نمی‌تواند آن را برگرداند، ناله او ناله کسی است که چیزی از دستش رفته و دیگر برنمی‌گردد.\nکسی که مشکلی برایش پیش آمد باید به خدا رجوع کند، به هر جا غیر خدا رجوع کند اشتباه رفته و دست‌خالی برمی‌گردد. پناهگاه انسان در سختی‌ها و مشکلات جز خدا نیست.\nمَنْ تَکَلَّمَ سَمِعَ نُطْقَهُ\nهرکس تکلم کند و حرفی بزند خدا می‌شنود.\nگاهی ما در وقت تنگ می‌کنیم که حتماً نیمه‌شب باخدا حرف بزنیم، برای حرف‌زدن باخدا با وضو باشیم باید آدم خوبی باشیم که باخدا حرف بزنیم، ولی نه؛\nگناهکار در همان صحنه گناه هم می‌تواند بگوید الله و خدا می‌شنود.\nهرکسی حرف بزند با صدا یا بی‌صدا، می‌شنود او از ضمیر باخبر است. در دل او را می‌شنود. احتیاج و ضعف او را می‌داند.\nدر قرآن فرموده ان الله سمیع الدعاء و یا وقتی گفته می‌شود: سمع الله لمن حمده؛ خدا حرف همه را می‌شنود حتی گنهکار را و کسی که به خدا اهانت کند و ناسزا بگوید، می‌شنود، اما تفاوت است بین شنیدن و ترتیب اثر دادن.\n(مانند پسر حریف شنو، نه اینکه دیگر فرزندان کر هستند؛ یعنی حرف من بر او اثر می‌گذارد و خواسته‌ام را انجام می‌دهد)\nخدا هم به حرف دعاکننده ترتیب اثر می‌دهد و حمد فرد حامد را می‌شنود. حرف فرعون را هم می‌شنود؛ اما به حرف موسی ترتیب اثر می‌دهد.\nاگر می‌خواهید حرف شما مقبول شود باید حامد، اهل ذکر و دعا باشید. طهارت قلبی داشته باشید، (حرف بد، ناروا و غیبت و تهمت نباشد) تا کلام شنیده شود.\nوَمَنْ سَکَتَ عَلِمَ سِرَّهُ\nاگر کسی ساکت باشد، خداوند سخن درونش را می‌شنود؛ چون خدا مثلمانی نیست که حرف پشت دیوار را نمی‌شنویم. آنچه را انسان بگوید و نگوید به آن آگاهی مطلق دارد.\nوَمَنْ عَاشَ فَعَلَیْهِ رِزْقُهُ\nهرکس زنده باشد و زندگی کند، رزق او بر عهده خداست. خدای متعال روزی همه را تضمین کرده. حضرت در نهج‌البلاغه در مورد رزق کلمات زیادی دارد.\nرزق مقسوم و تضمین شده است منتهی با دو قید:\nقید اول اینکه، اگر فردی ظالمی سر راه (رزق) نباشد. خدا برای همه رزقی معلوم کرده؛ ولی ممکن است ظالمی رزق دیگری را بخورد. چون نظام عالم، نظام اراده است؛ ولی ظالم باید در قیامت جواب ظلم خود را بدهد.\nقید دوم: خدا رزق ما را تضمین کرده؛ ولی اسراف و بریزوبپاش ما را تضمین نکرده.\nپیامبر دعا می‌فرمود؛ خدایا به من کفاف بده (در باب امور معیشتی)\nاین دعا و سنت پیامبر ص بوده.\nکفاف یعنی در شأن تو باشد. موجب ذلت و خواری تو نشود. اگر به آنچه دارید و مناسب است راضی باشید و اکتفا کنید، می‌بینید که رزق رسیده و خوب هم رسیده.\nنه‌فقط انسان بلکه همه موجودات نزد پروردگار پرونده دارند حتی حیوان نجس العین مثل سگ و خوک. خدا روزی آن‌ها را می‌دهد.\nمی‌فرماید در بیابان‌های دوردست خداوند صدا و ناله حیوانات را می‌شنود و رزقشان می‌دهد و به موجودات در اعماق اقیانوس‌هایی که بشر دست نیافته روزی آن‌ها می‌دهد.\nوَمَنْ مَاتَ فَإِلَیْهِ مُنْقَلَبُهُ\nهرکسی از دنیا برود، بازگشت به‌سوی اوست. إنَّا لِلَّهِ وَإِنَّا إِلَیْهِ رَاجِعُونَ\nلَمْ تَرَک الْعُیونُ فَتُخَبِّرَ عَنْک\nخدایا هیچ‌کس و هیچ چشمی تو را ندیده تا از تو خبر دهد تو ازلی بودی و کسی که ازلی است نمی‌تواند جسم باشد.\nدیدن مخصوص جسم و جسمانی است. موجود ازلی چون جسم ندارد قابل‌دیدن نیست. چون جسم نقص و حدوث است باید کسی او را خلق کرده باشد.\nدر بحث بلاغت بحثی تحت عنوان التفات هست؛ یعنی کلام به شکل غایب است؛ اما تبدیل به خطاب می‌شود؛ مانند سوره حمد که از ابتدا به‌صورت غایب بیان می‌شود و یک‌دفعه شکل مخاطب به خود می‌گیرد، إیاک نعبد، اهدنا.\nدر اینجا هم حضرت از غایب به مخاطب التفات می‌کند. اینکه خدا دیده‌شدنی نیست؛ ولی حاضر است. اینجا که صحبت از دیده‌نشدن هست حضرت خطاب می‌کند: ای خدایی که همه‌جا هستی و مخاطب مایی ولی دیده‌شدنی نیستی…\nبَلْ کنْتَ قَبْلَ الْوَاصِفِینَ مِنْ خَلْقِک\nبله قبل از اینکه مخلوقات بتوانند تو را وصف کنند بودی.\nلَمْ تَخْلُقِ الْخَلْقَ لِوَحْشَةٍ\nخدایا تو مخلوقات را خلق نکردی؛ چون ترس و وحشت داشتی.\nحاکمان دنیا، سپاه و نیرو تشکیل می‌دهند قلعه می‌سازند؛ چون وحشت دارند و می‌ترسند کسی حکومتشان را بگیرد.\nوَلَا اسْتَعْمَلْتَهُمْ لِمَنْفَعَهُ\nتو مردم را به کار نگرفتی که سودی به تو برسد. چنین نیست که از خدا بودن خود سودی ببرد.\nوَلَا یسْبِقُک مَنْ طَلَبْتَ وَلَا یقْلِتُک مَنْ أَخَذْتَ\nکسی را که تو طلب کنی برای گوشمالی، نمی‌تواند از دست تو فرار کند و اگر کسی را بخواهی مجازات کنی ممکن نیست از زیر بار مجازاتت شانه خالی کند.\nوَلَا ینْقُصُ سُلْطَانَک مَنْ عَصَاک\nخدایا کسی که تو را عبادت نمی‌کند و در ظاهر با تو جنگ می‌کند، نمی‌تواند در سلطنت تو نقص ایجاد کند.\nدر زد و خورده‌های دنیایی دو طرف خسارت می‌بینند؛ ولی در بارگاه الهی ضرر فقط یک‌طرفه و برای انسان گناهکار است؛ ولی خدا ضرر نمی‌کند.\nوَلَا یزِیدُ فِی مُلْکک مَنْ أَطَاعَک\nاگر کسی تو را اطاعت کند به تو چیزی اضافه نخواهد شد. عظمت و قدرت و علم و حیات خدا ذاتی است و چنین نیست که عبادت انسان به خدا عزت بدهد.\nوَلَا یرُدُّ أَمْرَک مَنْ سَخِطَ قَضَاءَک\nخدایا، اگر کسی با قضاوقدر و مقدرات تو دربیفتد و ناخشنود باشد، نمی‌تواند امر و قدر تو را طرد و دور کند.\nخدایا تو اراده کرده‌ای نام حسین ع بر بام عالم بدرخشد گرچه هزاران مأمون و متوکّل جمع شوند که نام حسین را محو کنند، شدنی نیست.\nاگر کسی از قضاوقدر ناخشنود باشد نمی‌تواند آن را تغییر دهد.\nامر، امر تکوینی است، آنچه که خدا اراده کرده. همه عالم دست‌به‌دست هم بدهند که خورشید از مغرب طلوع کند گریه و ضجه هم کنند شدنی نیست. امر همان است که خدا مقدر کرده و کار به اراده الهی است و با خوش‌آمدن یا نیامدن ما قابل‌تغییر نیست.\nدر حدیث قدسی آمده: «یا داوود ارید وترید» تو چیزی را اراده می‌کنی و چیزی را من اراده می‌کنم. در نهایت چیزی که من می‌خواهم، می‌شود نه آنچه تو می‌خواهی. چون قدرت من فوق قدرت تو است.\nالبته به یک شرط می‌توانی اراده خود را مانند اراده من کنی. اگر قدم در مسیر اراده من گذاشتی، اراده من بااراده تو همسو می‌شود. هرچه بخواهی من هم همان را اراده می‌کنم. ولی مسلماً بنده‌ای که به چنین درجه‌ای برسد خواهد گفت خدا با من چیزی از خود ندارد، هرچه تو بگویی همان است.\nاگر ما حاجتی داشته باشیم و نزد امامزاده‌ای برویم راحت‌تر حاجت می‌گیریم. تا اینکه نزد امام هشتم برویم… هرچه تقرب بیشتر باشد حاجت کمتر می‌شود.\nانسان جاهل دائماً از خدا این‌وآن می‌خواهد؛ ولی انسان عاقل می‌گوید خدایا تو می‌دانی امور را چطور پیش ببری، هرطور خودت می‌خواهی.\nامامزاده چون مقام قربش کمتر است واسطه می‌شود تا حاجتت را بگیری؛ ولی درک امام بالاتر است درخواستش هم از خدا کمتر است.\nوَلَا یسْتَغْنِ عَنْک مَنْ تَوَلَّی عَنْ أَمْرِک\nاگر کسی پشت به امر تو کند (امر تشرعی و احکام دین)، در انتها باز هم از تو بی‌نیاز نیست.\nفرد بی‌نماز شاید بتواند از خود بلاها را رفع کند ولی در آخر امر محتاج تو است پس چه بهتر که حرف تو را گوش بدهیم و به تو محتاج باشیم.\nکلُّ سِرٍّ عِنْدَک عَلَانِیةٌ وَکلُّ غَیبٍ عِنْدَک شِهَادَةٌ\nخدایا همه اسرار پیش تو آشکار است\nآنچه که برای ذیگران غیب است و مستور، برای تو عیان است. غیب برای بقیه است ولی برای خدا آشکار و واضح است.\nأَنْتَ الْأَبَدُ فَلَا إِمْدَالَک\nخدایا تو ابدی و دائمی هستی. هیچ سرانجام و تاریخ انقضایی برای تو نیست.\nأَنْتَ الْمَنْتَهِی فَلَا مَحِیصَ عِنْدَک\nتو یابانی و هیچ راه فراری جز آمدن به‌سوی تو نیست. همه باید در پایان به (خدا) برسند حتی مرتد و بی‌دین؛ اما رسیدن آن‌ها با شرمندگی است. ولی اگر در مسیر خدا باشد به خدا می‌رسد با سرافرازی و خوشحالی.\nوَأَنْتَ الْمَوْعِدُ فَلَا مَنْجَی مِنْک إِلَّا إِلَیْک\nخدایا تو همان وعده گاهی هستی که به سمت تو ختم می‌شویم تا به ثواب و جزاء اعمالمان برسیم. هیچ نجاتی نیست مگر خود تو.\nدر صحرای قیامت مگر راهی جز رحمت خدا و شفاعت اهل‌بیت هست. خدایا تو سرانجام کار، و وعده‌گاه تویی، همه باید نزد تو آییم و حساب پس دهیم. در آن لحظه تویی که می‌توانی نجات دهی و دستگیری کنی.\nبِیدِک نَاصِیةُ کلِّ دَابَّةٍ\nخدایا به دست توست موئی پیشانی [ناصیه] زمام و اختیار هر موجودی.\nوَإِلَیک مَصِیرُ کلِّ نَسْمَةٍ\nروح انسان لطیف است [نَسْمَة] و بازگشت همه ارواح به‌سوی خداست.\nسُبْحَانَک\nپاک و منزهی تو،\nسبحان از کلمات عجیب قرآن است. تمام نقص‌ها و ضعف‌ها را از خدا نفی می‌کنیم. خدایا تو عیب و نقصی نداری اگر ما هم خوبی داریم همه از تو است.\nسبحان، اثبات و بازگشت همه خیرها به خدا و نفی تمام عیب‌ها از خدا.\nسُبْحَانَک وَمَا أَعْظَمَ شَأْنَک\nخدایا تو هیچ نقصی نداری و چقدر عظمت تو بزرگ است. در عظمت تو هیچ نقص و ضعفی راه ندارد و کوچک نیست. اگر ما هم عظمتی داریم از تو گرفته‌ایم.\nسُبْحَانَک مَا أَعْظَمَ مَا تَرَی مِنْ خَلْقِک\nخدا با خلقت تو چقدر بزرگ است.\nخلقت خدا با همه عظمت نقص‌هایی دارد نه در ذات، بلکه انسان که مخلوق خداست شهوت‌پرست و بداخلاق است، مخلوقات خدا بااراده خود نقص‌هایی دارند، خدایا مخلوقات عظمت دارند؛ ولی بدی‌هایشان مربوط به تو نیست، تو همه خوبی هستی آن‌ها خودشان بد شده‌اند.\nچقدر عالم خلق بزرگ است. انسان هوش و استعداد این عالم را نمی‌فهمد.\nهرچه علم پیشرفت می‌کند خداشناسی بیشتر می‌شود. کسانی که نمی‌فهمند می‌گویند می‌ترسیم علم آن‌قدر پیشرفت کند که خدا ترد شود و انکار شود. نمی‌فهمند که هرچه علم پیشرفت کند خدا بیشتر شناخته می‌شود.\nهرچه علم بیشتر، دقیق و ریزتر می‌شود و سبحان‌الله بلندتر می‌شود.\nوَمَا أَصْغَرَ کلَّ عَظِیمَةٍ فِی جَنْبِ قُدْرَتِک\nاین‌همه عظمت در مقابل قدرت تو چقدر صغیرند.\nما وقتی با خود می‌سنجیم می‌گوییم آسمان و خورشید، خیلی بزرگ هستند؛ اما همه نظام خلقت در مقابل قدرت خدا هیچ است.\nیک عالم و دانشمند تمام علم و توانایی خود را می‌گذارد تا یک کتاب بنویسد، تجلی علم او این کتاب است.\nخدا این‌همه عظمت را که خلق کرده، ذره‌ای از قدرت خدا شده این عالم باعظمت.\nاین‌همه عظمت در برابر قدرت تو هیچ است، قدرت تو انتهایی ندارد.\nوَمَا إِهَوْلَ مَا نَرَی فِی مَلَکوتِک\nچقدر هولناک است، چقدر باشکوه است آنچه از ملکوت تو می‌بینیم.\n(ملکوت؛ آنچه که در ورای این عالم ماده است).\nهرچه می‌بینیم ملکوتی دارد. ملکوت یک‌خانه ممکن است نورانی باشد. خانه‌ای قبلاً به‌خاطر موسیقی که در آن گذاشته شده اثر وضعی آن مانده؛ لذا در ماشین قرآن بگذار تا آفات و شرور قبلی از بین برود.\nخدایا چقدر ملکوت و باطن اشیا شکوهمند است.\nمعلوم است که حضرت امیر به ملکوت عالم راه دارد؛ ولی ما نمی‌بینیم.\nاز ظاهر این عالم انگشت بدهان شده‌ایم بماند، چقدر باطن و ملکوت عالم عجیب است.\nوَمَا أَحْقَرُ ذَلِک فِی مَغَابِ عَنَّا مِنْ سُلْطَانِک\nچه دنیا و چه ملکوت عالم، همه در مقابل سلطنت تو هیچ است.\nحضرت سه مرحله را بیان می‌کند.\nالف) عالم خلقت، چقدر عظیم و بزرگ است؛ اما در مقابل ملکوت هیچ است.\nب) چقدر عالم ملکوت بزرگ، عجیب و وحشت‌انگیز است؛ اما در مقابل سلطنت خدا هیچ است.\nج) سلطنت خدا ورای همه این‌هاست.\nمعلوم است عالم شمعی از قدرت و عظمت خدا. ذات، حقیقت و عظمت خدا بر همه آن‌ها سیطره دارد و از همه آن‌ها بزرگ‌تر است.\nچقدر حقیر و کوچک است آنچه را از عالم خلقت و ملکوت می‌بینیم نسبت به آنچه که از ما پوشیده است از عظمت و حقیقت و سلطنت.\nوَمَا أَسْبَغَ نِعْمَک فِی الدُّنْیا وَمَا أَصْغَرَ فِی نِعَمِ الْآخِرَةِ\nچقدر نعمت‌های تو در دنیا کامل و گسترده‌اند [أَسْبَغَ]\nو چقدر این نعمت‌های فراوان دنیا در برابر نعمت‌های آخرت کوچک و ناقص‌اند.\nاگر نعمت بین باشم خدایا من خیلی نعمت داده. نعمت‌های فراوانی داریم که باید بادقت به دست بیاوریم، نعمت احساس، محبت، سلوک.\nما می‌توانیم به خدا برسیم.\nکسی در محضر امام صادق ع اظهار فقر کرد، امام فرمود تو فقیر نیستی؛ اما او اصرار بر فقر و نداری خود کرد که دو روز است که غذا نخوردم لباس ندارم و… امام فرمود منظور تو اینها است؛ اما منظور من اینها نیست تو فقیر نیستی، آیا حاضری حب علی ع را بدهی و چند دینار بگیری، گفت: نه. اصلاً عالم راهم بدهند حاضر به چنین کاری نیستم. امام فرمود: ثروت داری، تو اشتباه دیدی، پول را ثروت دیدی؛ اما مال، حب امیرالمؤمنین است.\nنعمت‌های آخرت هم فراوان‌ترند و هم کامل‌تر.\nمثلاً در دنیا فضیلت امیرمؤمنان را می‌خوانیم و لذت می ببریم؛ اما در آخرت از فضایل حضرت چیزهایی خواهیم دانست که در دنیا میسر نبود به‌خاطر تحریف‌ها و دشمنی‌ها با حضرت نگذاشتند از فضایل بیشتر ایشان بهره ببریم.\nچنانچه کسی عالم بزرگوار آقا سید احمد خوانساری را در عالم رؤیا دید که مشغول خواندن کتاب است. گفته بود اینجا هم کتاب می‌خوانی؟ فرموده بود در دنیا خیلی از فضایل امیرالمؤمنین را ما نگفته بودند از بس عظمت داشت و مردم دنیا تحمل نداشتند. ما که برزخ آمدیم تازه فضایل علی را می‌خوانیم.\nپیامبر اکرم ص فرمود در مورد علی حرف‌هایی هست ولی می‌ترسم مردم مثل مسیحیت بگویند که علی خداست.\nخدایا به عظمت امیرالمؤمنین ما را در دنیا و آخرت از ایشان جدا مگردان.\nالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِینَ","بخش دوم\nمتن:\nالملائكة الكرام‏:\nمِنْ مَلَائِكَةٍ أَسْكَنْتَهُمْ سَمَاوَاتِكَ وَ رَفَعْتَهُمْ عَنْ أَرْضِكَ هُمْ أَعْلَمُ خَلْقِكَ بِكَ وَ أَخْوَفُهُمْ لَكَ وَ أَقْرَبُهُمْ مِنْكَ لَمْ يَسْكُنُوا الْأَصْلَابَ وَ لَمْ يُضَمَّنُوا الْأَرْحَامَ وَ لَمْ يُخْلَقُوا مِنْ مَاءٍ مَهِينٍ وَ لَمْ يَتَشَعَّبْهُمْ رَيْبُ الْمَنُونِ وَ إِنَّهُمْ عَلَى مَكَانِهِمْ مِنْكَ وَ مَنْزِلَتِهِمْ عِنْدَكَ وَ اسْتِجْمَاعِ أَهْوَائِهِمْ فِيكَ وَ كَثْرَةِ طَاعَتِهِمْ لَكَ وَ قِلَّةِ غَفْلَتِهِمْ عَنْ أَمْرِكَ لَوْ عَايَنُوا كُنْهَ مَا خَفِيَ عَلَيْهِمْ مِنْكَ لَحَقَّرُوا أَعْمَالَهُمْ وَ لَزَرَوْا عَلَى أَنْفُسِهِمْ وَ لَعَرَفُوا أَنَّهُمْ لَمْ يَعْبُدُوكَ حَقَّ عِبَادَتِكَ وَ لَمْ يُطِيعُوكَ حَقَّ طَاعَتِكَ.\nعصيان الخلق‏:\nسُبْحَانَكَ خَالِقاً وَ مَعْبُوداً بِحُسْنِ بَلَائِكَ عِنْدَ خَلْقِكَ، خَلَقْتَ دَاراً وَ جَعَلْتَ فِيهَا مَأْدُبَةً مَشْرَباً وَ مَطْعَماً وَ أَزْوَاجاً وَ خَدَماً وَ قُصُوراً وَ أَنْهَاراً وَ زُرُوعاً وَ ثِمَاراً، ثُمَّ أَرْسَلْتَ دَاعِياً يَدْعُو إِلَيْهَا فَلَا الدَّاعِيَ أَجَابُوا وَ لَا فِيمَا رَغَّبْتَ رَغِبُوا وَ لَا إِلَى مَا شَوَّقْتَ إِلَيْهِ اشْتَاقُوا، أَقْبَلُوا عَلَى جِيفَةٍ قَدِ افْتَضَحُوا بِأَكْلِهَا وَ اصْطَلَحُوا عَلَى‏ حُبِّهَا، وَ مَنْ عَشِقَ شَيْئاً أَعْشَى بَصَرَهُ وَ أَمْرَضَ قَلْبَهُ، فَهُوَ يَنْظُرُ بِعَيْنٍ غَيْرِ صَحِيحَةٍ وَ يَسْمَعُ بِأُذُنٍ غَيْرِ سَمِيعَةٍ، قَدْ خَرَقَتِ الشَّهَوَاتُ عَقْلَهُ وَ أَمَاتَتِ الدُّنْيَا قَلْبَهُ وَ وَلِهَتْ عَلَيْهَا نَفْسُهُ، فَهُوَ عَبْدٌ لَهَا وَ لِمَنْ فِي يَدَيْهِ شَيْ‏ءٌ مِنْهَا، حَيْثُمَا زَالَتْ زَالَ إِلَيْهَا وَ حَيْثُمَا أَقْبَلَتْ أَقْبَلَ عَلَيْهَا، لَا يَنْزَجِرُ مِنَ اللَّهِ بِزَاجِرٍ وَ لَا يَتَّعِظُ مِنْهُ بِوَاعِظٍ، وَ هُوَ يَرَى الْمَأْخُوذِينَ عَلَى الْغِرَّةِ حَيْثُ لَا إِقَالَةَ [لَهُمْ‏] وَ لَا رَجْعَةَ، كَيْفَ نَزَلَ بِهِمْ مَا كَانُوا يَجْهَلُونَ وَ جَاءَهُمْ مِنْ فِرَاقِ الدُّنْيَا مَا كَانُوا يَأْمَنُونَ وَ قَدِمُوا مِنَ الْآخِرَةِ عَلَى مَا كَانُوا يُوعَدُونَ.\nفَغَيْرُ مَوْصُوفٍ مَا نَزَلَ بِهِمْ\nترجمه:\nاز جمله مخلوقات تو فرشتگانى هستند که آنها را در آسمان هاى خود سکونت بخشيدى و از زمينت بالا بردى. آنها از همه آفريده هاى تو نسبت به تو آگاهترند، و پيش از همه، از تو خائفند، و از همه به تو نزديکتر. آنها هرگز در صُلب پدران قرار نداشته و رحم مادران آنها را در برنگرفته، از آبى پَست، آفريده نشده، و حوادث زمان و مرگ و ميرها آنها را از يکديگر جدا نساخته است;\nولى آنان با اين مقام قرب که نسبت به ساحت مقدّست دارند و منزلتى که نزد تو يافته اند و عشق و علاقه اى که تنها به تو دارند و طاعات فراوانى که براى تو انجام مى دهند و از فرمان تو کمتر غفلت مى کنند، با اين همه، هرگاه آنچه را از عظمت تو بر آنها پوشيده است مشاهده مى کردند، اعمال خويش را حقير مى شمردند و بر خود عيب مى گرفتند (و آن را شايسته مقام تو نمى دانستند) و به خوبى مى فهميدند که حقّ عبادتت را هرگز انجام نداده اند و آن گونه که سزاوار مقام توست، اطاعت ننموده اند.\n(خداوندا) خالق و معبودى هستى پاک و منزّه! تو را (به خاطر نعمت هايى که به آفريدگان عطا کرده اى) تنزيه و ستايش مى کنم! سرايى بزرگ آفريده اى (به نام سراى آخرت) که در آن انواع نعمت ها را قرار داده اى: آشاميدنى ها، خوردنى ها، همسران، خدمتکاران، کاخ ها، نهرها، درختان بارور و ميوه ها. سپس دعوت کننده اى فرستاده اى که مردم را به سوى آن همه نعمت فرا خواند; ولى نه دعوت او را اجابت کردند و نه به آنچه ترغيب فرموده اى، اظهار علاقه نمودند و نه به آنچه تشويق نموده اى مشتاق شدند; (بلکه) به مردارى روى آوردند که با خوردن آن رسوا گشته اند، و (عجب اينکه) در محبّت و دوستى آن با هم توافق کرده اند.\nآرى! هر کس به چيزى عشق ورزد چشم او را ناتوان و قلب و فکر او را بيمار مى سازد; در نتيجه با چشمى معيوب (به همه چيز) مى نگرد و با گوشى ناشنوا مى شنود. شهوات و خواسته هاى دل جامه عقلش را دريده، و دنيا پرستى، قلبش را ميرانده، و تمام وجودش شيفته آن شده است; از اين رو او بنده دنياست و بنده هر کسى که چيزى از دنيا را در دست دارد! به هر طرف دنيا بلغزد، او هم مى لغزد و به هر سو رو کند، به همان سو رو مى کند. نه نهى کننده الهى را پذيرا مى شود و نه موعظه هيچ واعظ ربّانى را; در حالى که با چشم خود غافلانى را مى بيند که ناگهان درچنگال مرگ گرفتار مى شوند; در آنجا که نه تقاضاى عفو پذيرفته مى شود و نه بازگشتى وجود دارد (آرى! او مى بيند) چگونه حوادث دردناکى که از آن خبر نداشته اند، بر سر آنها فرود آمده، و دنيايى را که جايگاه امنى مى پنداشتند، از آنها جدا شده، و به آنچه از آخرت به آنها وعده داده شده بود، رسيده اند.\n(آرى!) حوادثى بر سر آنها فرود آمده که با هيچ بيانى قابل توصيف نيست (اما اينها پند نمى گيرند!)\nتفسیر:\nمعروف به خطبه الزهرا\nبخش اول در مورد توحید و بخش دوم در مورد ملائکه است.\nالبته توضیحات مفصل در مورد ملائکه در خطبه یک آمده است.\nوَ مِنْها مِنْ مَلائِکةٍ أَسْکنْتَهُمْ سَماواتِک\nخداوند موجودات شگفت‌انگیزی خلق کرده، موجوداتی که در این آسمان و زمین نشانه عظمت هستند و آن ملائکه‌اند.\nو بعضی از این ملائکه در آسمان جای دارند و بعضی در زمین.\nالبته ساکن زمین نیستند، بلکه در زمین برای رفع امور مردمان هستند. در صحیفه سجادیه، امام سجاد فرمودند:\nبر هر کوهی ملکی ایستاده است و آن ملک کوه‌ها را حفاظت می‌کند؛ این ملائکه اهل زمین نیستند، ولی مأموریتشان زمینی است،\nولی گروه دیگری هستند که آسمان‌نشین‌اند.\nوَ رَفَعْتَهُمْ عَنْ أَرْضِک\nگروهی از ملائکه را در آسمان برتری داد و از زمین بالا برد.\nاین رفعت می‌تواند رفعت مسکنی باشد و هم مقامی؛ یعنی مسکن آن‌ها را در آسمان قرارداد و مقامشان مقام آسمانی شد،\nچون ملائکه هم درجه‌بندی دارند و در یک سطح نیستند؛ بعضی مقامشان پایین‌تر است و با زمینیان سروکار دارند.\nهُمْ أَعْلَمُ خَلْقِک بِک\nخدایا، ملائکه عالم‌ترین و آگاه‌ترین موجودات نسبت به تو هستند.\nهیچ موجودی در عالم خلقت به خدا مثل ملائکه آگاه و عالم نیست و حقیقت خدا را نمی‌شناسد.\nاین سؤال شاید پیش بیاید که چرا اعلم خلق، ملائک هستند؟\nیعنی از پیامبران اعلم‌تر هستند؛ دو نظریه وجود دارد:\nنظریه اول مطلقاً می‌گویند انبیا و ائمه از همه ملائکه بالاترند (مثل حدیث معراج؛\nجبرئیل جزو بالاترین ملائکه است، ولی نسبت به پیامبر نمی‌تواند از یک جایی بالاتر برود؛ پس طبق این روایات ملائکه بالا هستند، اما انبیا از آن‌ها بالاترند).\nدوم؛ آیا ملائکه از همه انسان‌ها غیر از امامان و پیامبران بالاتر هستند؟\nاین هم دو بحث دارد:\nاول، مقام قوه؛\nدوم، فعل است.\nانسان قوه‌ای دارد که می‌تواند از ملائکه بالاتر برود. تفاوت انسان، حیوان و ملک در این است که حیوانات قوه بلاعقل دارند،\nملائکه عقل بلا شهوت دارند،\nانسان عقل و شهوت را هم‌زمان دارد.\nاگر کسی بتواند همراه عقل از سطح شهوت بگذرد و به جایگاه بلندی برسد، از ملائکه که عقل محض هستند بیشتر رشد می‌کند.\nولی در مقام فعلیت و عمل؛\nآیا انسان‌ها توانسته‌اند از ملائک بالاتر بروند؟\nغالب انسان‌ها خیر؛ حتی به‌اندازه کوچک‌ترین و پایین‌ترین سطح ملائکه هم نرسیده‌اند، چه برسد به مقام بالایی مثل جبرئیل.\nولی در بین انسان‌ها کسانی هستند که قوه شهوت را کنار زده و به قوه فعل رسیده و از ملائکه بالاتر دست یافته‌اند. اما ملائکه از غالب انسان‌ها بالاتر و آگاه‌ترند، چون انسان‌ها دنباله‌روی و تلاش نمی‌کنند؛ اما اگر واقعاً کسی تلاش کند، به جایی می‌رسد که از ملائکه بالاتر باشد.\nوَ أَخْوَفُهُمْ لَک\nملائکه خائف و ترسان‌ترین به خدا هستند.\nوَ أَقْرَبُهُمْ مِنْک\nو آن‌ها به تو نزدیک‌تر هستند.\nاین سه جمله معیار و قاعده ارزشمندی دارند:\nاول معرفت،\nدوم خوف،\nسوم تقرب.\nهرچه معرفت و خوف انسان بیشتر باشد، باعث تقرب می‌شود.\nترس به معنای اینکه مبادا از چشم خدا بیفتم.\nحتی در مورد انسان‌ها هم صدق دارد؛ هرچه انسان شناختش بیشتر باشد، به تقرب نزدیک‌تر می‌شود.\nلَمْ یسْکنُوا الْأَصْلابَ وَ لَمْ یضَمَّنُوا الْأَرْحامَ\nملائکه هیچ‌گاه ساکن اصلاب (صلب پدران) نبودند و هیچ‌گاه در رحم مادران قرار نگرفتند.\nوَ لَمْ یخْلَقُوا مِنْ ماءٍ مَهِینٍ\nو هیچ‌گاه از آب مهین (پست) متولد نشدند.\nتفاوت عمده انسان و ملائکه همین است.\nانسان به‌خاطر جسمیت در مسیر خلقت، از صلب پدران و رحم مادران و از یک آب مهین (نطفه) متولد می‌شود؛ اما خلق ملائکه از نور است و دارای جسم نیستند.\nوَ لَمْ یتَشَعَّبْهُمْ رَیبُ الْمَنُونِ\nآن‌ها را شعبه، شعبه نکرد.\nحوادث روزگار مانند زلزله، سختی، بیماری، مشاغل و مرگ، انسان‌ها را می‌تواند از هم دور کند، اما ملائکه این‌طور نیستند.\nهم در خلقت و هم در مرگ مانند انسان نیستند.\nالبته آن‌ها هم روزی می‌میرند و قرآن فرموده همه موجودات می‌میرند و ملائکه هم جز آن‌هاست؛ زمانی که در صوراسرافیل دمیده شود.\nحضرت از بیان ملائکه و حالات آن‌ها به ما درس زندگی می‌دهد؛ ملائک معرفت، خضوع و تقرب دارند؛ ما هم باید داشته باشیم.\nوَ إِنَّهُمْ عَلی مَکانِهِمْ مِنْک وَ مَنْزِلَتِهِمْ عِنْدَک وَ اسْتِجْماعِ أَهْوائِهِمْ فِیک\nملائک در آن جایگاه و منزلتی که نزد خداوند دارند، در علاقه و اشتیاق تو متحد هستند.\nوَ کثْرَةِ طاعَتِهِمْ لَک وَ قِلَّةِ غَفْلَتِهِمْ عَنْ أَمْرِک\nبا اینکه بسیار اهل طاعت هستند\nو غفلتشان از اوامر خدا بسیار کم است.\nلَوْ عاینُوا کنْهَ ما خَفِی عَلَیهِمْ مِنْک لَحَقَّرُوا أَعْمالَهُمْ\nاگر ملائک عظمت پنهان تو را ببینند، باز تو را کم شناخته‌اند، چون تو لایتناهی هستی و انتها نداری؛ می‌گویند چقدر اعمال ما کم است.\nوَ لَزَرَوْا عَلی أَنْفُسِهِمْ\nبر خود عیب می‌گیرند که وای بر ما، چقدر عبادت و سجده در برابر عظمت الهی کم داریم.\nوَ لَعَرَفُوا أَنَّهُمْ لَمْ یعْبُدُوک حَقَّ عِبادَتِک وَ لَمْ یطِیعُوک حَقَّ طاعَتِک\nبا تمام جان می‌فهمند حق عبادت و معرفت تو را ادا نکردند و اعمالشان به چشم نمی‌آید.\nچند نکته مهم نهفته است:\n۱. طاعت ملائک (باید در حد خود از اطاعت ملائک درس بگیریم) و تشویق به عبادت شویم.\n۲. نکته مهم: آیا ملائکه اختیار دارند یا ندارند؟ در بین عموم گفته شده ملائک اختیار ندارند و خدا هرچه گفته انجام می‌دهند.\nولی حقیقت آن است که ملائک اختیار دارند؛ شهوت ندارند.\nالبته از روی غفلت، نه از روی شهوت؛ و غفلت آنان کم است، نه اینکه گناه کنند؛ اما همین غفلت برایشان حکم گناه دارد.\nو این غفلت آنان را به پایین سقوط می‌دهد.\nیک عده با اختیار خود غفلت می‌کنند و یک عده با اختیار خود توجه به خدای متعال دارند و این علت بالا و پایین‌رفتنشان است.\nسُبْحانَک خالِقاً وَ مَعْبُوداً\nای خالق ما، تو پاک و منزه هستی از هرگونه عیب و ناپاکی.\nبِحُسْنِ بَلائِک عِنْدَ خَلْقِک خَلَقْتَ داراً\nخدایا، تو به‌خاطر امتحان‌های نیکو که از مخلوقات گرفتی، خلق کردی\nخانه‌ای (بهشت) را.\nتو در این دنیا ما را امتحان کردی و امتحان تو به عسروحرج نبوده، بلکه امتحان ادب، ایثار و خوش‌اخلاقی بوده؛ امتحان کریمان بود\nکه سرانجام آن بهشت است.\nوَ جَعَلْتَ فِیها مَأْدُبَةً\nدر این بهشت مأدبه قراردادی.\nمأدبه از ادب گرفته شده، یعنی یک غذای شیرین و لذیذی که مهمانان را به آن دعوت می‌کنند. در آن بهشتی که نتیجه امتحان توست، یک سفره‌ای پهن کرده‌اند…\nمَشْرَباً وَ مَطْعَماً وَ أَزْواجاً وَ خَدَماً وَ قُصُوراً وَ أَنْهاراً وَ زُرُوعاً وَ ثِماراً\nنوشیدنی، خوردنی‌ها، همسران، خدمه، قصرها، چشمه‌ها، درختان و میوه‌ها همه آماده شده‌اند برای شخصی که در دنیا امتحانات را درست داده و سرانجام پیروزمندانه و باعزت و احترام به بهشت می‌رود.\nثُمَّ أَرْسَلْتَ داعِیاً یدْعُو إِلَیها\nخدایا، تو دعوت‌کننده‌ای فرستادی (انبیا) که مأمور به دعوت به‌سوی بهشت بودند.\nفَلا الدّاعِی أَجابُوا وَ لا فِیما رَغَّبْتَ رَغِبُوا\nمردم دعوت انبیا را اجابت نکردند و در آن چیزی که خدا رغبت داشت، مردم رغبت نشان ندادند.\nحضرت اول بهشت را ترسیم می‌کند؛ ما روی خوش‌نشان ندادیم؛ در عوض دل به چه بستیم؟\nأَقْبَلُوا عَلی جِیفَةٍ قَدِ افْتَضَحُوا بِأَکلِها\nمردم به یک حیوان مرداری دل دادند؛ همین که سراغ این حیوان مرده رفتند، خودشان را مفتضح کردند.\nحضرت دنیاپرست را به کفتاری تشبیه کردند که دور مردارها جمع می‌شوند و رسوایی و بی‌آبرویی به بار می‌آورند.\nوَ اصْطَلَحُوا عَلی حُبِّها\nدنیاپرستان در دوستی دنیا، به‌جای آخرت، با هم صلح کردند.\nوَ مَنْ عَشِقَ شَیئاً أَعْشی بَصَرَهُ\nهرکس به چیزی عشق بورزد، آن عشق چشم او را کور می‌کند.\nوَ أَمْرَضَ قَلْبَهُ\nو قلب را مریض می‌کند.\nفَهُوَ ینْظُرُ بِعَینٍ غَیرِ صَحِیحَةٍ\nآدم کم‌بینا درست نمی‌تواند ببیند.\nوَ یسْمَعُ بِأُذُنٍ غَیرِ سَمِیعَةٍ\nشنوایی او از دست می‌رود و حقایق و بهشت را نمی‌بیند، اما دنیا و گناه را خوب می‌بیند.\nگوش و چشم حقایق بین ندارد.\nقَدْ خَرَقَتِ الشَّهَواتُ عَقْلَهُ وَ أَماتَتِ الدُّنْیا قَلْبَهُ\nشهوت عقل او را از بین می‌برد. دنیا\nقلب او را می‌میرند.\nوَ وَلِهَتْ عَلَیها نَفْسُهُ فَهُوَ عَبْدٌ لَها\nتمام وجودش شیفته دنیا می‌شود و به‌جای بهشت، دنیا را انتخاب می‌کند.\nوَ لِمَنْ فِی یدَیهِ شَیءٌ مِنْها\nعبد کسی می‌شود که دنیادار است.\nحَیثُما زالَتْ زالَ إِلَیها\nهر طرفی که دنیا می‌رود، او هم می‌رود.\nلا ینْزَجِرُ مِنَ اللهِ بِزاجِرٍ وَ لا یتَّعِظُ مِنْهُ بِواعِظٍ\nدیگر حرف هیچ واعظی را قبول نمی‌کند.\nهیچ موعظه الهی در جان او نمی‌نشیند.\nوَ هُوَ یری الْمَأْخُوذِینَ عَلَی الْغِرَّةِ\nو می‌بیند رفقایی که فریب‌خورده و بیخ گلویشان را گرفته‌اند.\nحَیثُ لا إِقالَةَ وَ لا رَجْعَةَ\nکسی که در دنیا کار او تمام شد، بازگشت به دنیا ندارد.\nکیفَ نَزَلَ بِهِمْ ما کانُوا یجْهَلُونَ\nمی‌بیند مرگی که از آن غافل بود نازل می‌شود و به سراغ او می‌آید.\nوَ جاءَهُمْ مِنْ فِراقِ الدُّنْیا ما کانُوا یأْمَنُونَ\nمرگ به سمت غافلان می‌آید، درحالی‌که آن‌ها در دنیا خود را در امنیت می‌دانستند.\nوَ قَدِمُوا مِنَ الْآخِرَةِ عَلی ما کانُوا یوعَدُونَ فَغَیرُ مَوْصُوفٍ ما نَزَلَ بِهِمْ\nآن‌ها وارد بر قیامت می‌شوند به‌تمامی وعده و وعیدهایی که خداداده بود، و از آنچه به آن‌ها نازل شده می‌بینند که وصف‌ناپذیر است.\nاللَّهُمَّ أَخْرِجْ حُبَّ الدُّنْیا مِنْ قُلُوبِنا","بخش سوم\nمتن:\nاجْتَمَعَتْ عَلَيْهِمْ سَكْرَةُ الْمَوْتِ وَ حَسْرَةُ الْفَوْتِ، فَفَتَرَتْ لَهَا أَطْرَافُهُمْ وَ تَغَيَّرَتْ لَهَا أَلْوَانُهُمْ، ثُمَّ ازْدَادَ الْمَوْتُ فِيهِمْ وُلُوجاً، فَحِيلَ بَيْنَ أَحَدِهِمْ وَ بَيْنَ مَنْطِقِهِ وَ إِنَّهُ لَبَيْنَ أَهْلِهِ يَنْظُرُ بِبَصَرِهِ وَ يَسْمَعُ بِأُذُنِهِ عَلَى صِحَّةٍ مِنْ عَقْلِهِ وَ بَقَاءٍ مِنْ لُبِّهِ، يُفَكِّرُ فِيمَ أَفْنَى عُمُرَهُ وَ فِيمَ أَذْهَبَ دَهْرَهُ، وَ يَتَذَكَّرُ أَمْوَالًا جَمَعَهَا أَغْمَضَ فِي مَطَالِبِهَا وَ أَخَذَهَا مِنْ مُصَرَّحَاتِهَا وَ مُشْتَبِهَاتِهَا، قَدْ لَزِمَتْهُ تَبِعَاتُ جَمْعِهَا وَ أَشْرَفَ عَلَى فِرَاقِهَا، تَبْقَى لِمَنْ وَرَاءَهُ [يُنَعَّمُونَ‏] يَنْعَمُونَ فِيهَا وَ يَتَمَتَّعُونَ بِهَا، فَيَكُونُ الْمَهْنَأُ لِغَيْرِهِ وَ الْعِبْ‏ءُ عَلَى ظَهْرِهِ وَ الْمَرْءُ قَدْ غَلِقَتْ رُهُونُهُ بِهَا، فَهُوَ يَعَضُّ يَدَهُ نَدَامَةً عَلَى مَا أَصْحَرَ لَهُ عِنْدَ الْمَوْتِ مِنْ أَمْرِهِ وَ يَزْهَدُ فِيمَا كَانَ يَرْغَبُ فِيهِ أَيَّامَ عُمُرِهِ، وَ يَتَمَنَّى أَنَ‏ الَّذِي كَانَ يَغْبِطُهُ بِهَا وَ يَحْسُدُهُ عَلَيْهَا قَدْ حَازَهَا دُونَهُ؛ فَلَمْ يَزَلِ الْمَوْتُ يُبَالِغُ فِي جَسَدِهِ حَتَّى خَالَطَ لِسَانُهُ سَمْعَهُ، فَصَارَ بَيْنَ أَهْلِهِ لَا يَنْطِقُ بِلِسَانِهِ وَ لَا يَسْمَعُ بِسَمْعِهِ، يُرَدِّدُ طَرْفَهُ بِالنَّظَرِ فِي وُجُوهِهِمْ يَرَى حَرَكَاتِ أَلْسِنَتِهِمْ وَ لَا يَسْمَعُ رَجْعَ كَلَامِهِمْ؛ ثُمَّ ازْدَادَ الْمَوْتُ الْتِيَاطاً بِهِ [فَقَبَضَ بَصَرَهُ كَمَا قَبَضَ سَمْعَهُ‏] فَقُبِضَ بَصَرُهُ كَمَا قُبِضَ سَمْعُهُ وَ خَرَجَتِ الرُّوحُ مِنْ جَسَدِهِ فَصَارَ جِيفَةً بَيْنَ أَهْلِهِ قَدْ [أُوحِشُوا] أَوْحَشُوا مِنْ جَانِبِهِ وَ تَبَاعَدُوا مِنْ قُرْبِهِ، لَا يُسْعِدُ بَاكِياً وَ لَا يُجِيبُ دَاعِياً\nترجمه:\nشدائد و سَکَرات مرگ، و حسرت از دست دادن (همه چيز) بر آنها هجوم آورده، و به خاطر آن، اعضاى پيکرشان سُست مى شود و در برابر آن، رنگ خود را مى بازند;\nسپس مرگ تدريجاً در آنها نفوذ مى کند و بين آنها و زبانشان جدايى مى افکند، در حالى که ميان خانواده خود قرار دارد و با چشم خود به آنها نگاه مى کند، با گوش سخنانشان را مى شنود، عقلش سالم و فکرش برجا است. (در اين هنگام، از خواب غفلت بيدار مى شود:) فکر مى کند که عمرش را براى چه چيزهايى بر باد داده و روزگارش را در چه راهى سپرى نموده است. به ياد ثروت هايى مى افتد که گردآورى کرده; در جمع آن چشم بر هم گذارده و از حلال و حرام و مشکوک (هر چه به دستش آمده) در اختيار گرفته است، گناه جمع آورى آن، بر دامانش نشسته، و هنگام جدايى از آن رسيده است! (آرى!) اين اموال براى بازماندگان او به جاى مى ماند و از آن بهره مى گيرند و متنعّم مى شوند! لذّت و آسايش آن براى ديگران است و سنگينى گناهانش بر دوش او! و او گروگان اين اموال است. اين در حالى است که به خاطر امورى که به هنگام مرگ براى او روشن شده، دست خود را از پشيمانى مى گزد (و انگشت ندامت به دندان مى گيرد!) نسبت به آنچه در تمام عمر به آن علاقه داشت، بى اعتنا مى شود و آرزو مى کند اى کاش اين اموال به دست آن کس مى رسيد که در گذشته به ثروت او غبطه مى خورد و بر آن حسد مىورزيد، (تا وبال جانش نگردد.) \nسپس مرگ همچنان در وجود او پيشروى مى کند، تا آنجا که گوشش همچون زبانش از کار مى افتد; به طورى که در ميان خانواده اش نه زبان سخن گفتن دارد ونه گوش براى شنيدن. پيوسته به صورت آنها نگاه مى کند، حرکات زبانشان را مى بيند، ولى صداى آنان را نمى شنود. سپس چنگال مرگ در او بيشتر فرو مى رود! چشمش نيز همانند گوشش از کار مى افتد و روح او از بدنش براى هميشه خارج مى شود. در اين هنگام، به صورت مردارى در ميان خانواده اش قرار مى گيرد، که از نشستن نزد او وحشت مى کنند و از او فاصله مى گيرند. (فرياد سوگواران بر مى خيزد،) ولى نمى تواند سوگوارانش را يارى دهد و نه به کسى که او را صدا مى زند، پاسخ گويد.\nتفسیر:\nحضرت در این بخش خطبه، حالاتی را که در لحظه مرگ بر انسان‌ها عارض می‌شود بیان فرموده‌اند.\nفَغَیْرُ مَوْصُوفٍ مَا نَزَلَ بِهِمْ\nدنیاطلبان در لحظه مرگ حالاتی دارند که غیرقابل‌توصیف است. کسی که تمام وجود او تعلق است، چه سختی و رنجی در هنگام مرگ می‌کشد، وصف‌شدنی نیست.\nفقط مقداری را حضرت برای آمادگی ذهنی می‌فرمایند.\nاجْتَمَعَتْ عَلَیْهِمْ سَکْرَةُ الْمَوْتِ وَ حَسْرَةُ الْفَوْتِ\nدو گرفتاری بزرگ برای محتضر پیش می‌آید که هر کدام برای بیچارگی فرد بس است، چه برسد به آنکه با هم به وقوع بپیوندد.\n۱- لحظات جان‌دادن، محتضر ازخودبی‌خود (سَکْرَة) است. مستی حاصل از نوشیدن شراب نیست؛ مستی حاصل از استیصال و بیچارگی است.\n۲- لحظه‌ای که همه دلخوشی‌ها را از دست می‌دهد و باید از همه تعلقات دنیوی دل بکند.\nوَ تَغَیَّرَتْ لَهَا أَلْوَانُهُمْ، ثُمَّ ازْدَادَ الْمَوْتُ فِیهِمْ وُلُوجاً\nرنگ صورت آن‌ها تغییر می‌کند.\nلحظه‌به‌لحظه آثار مرگ بیشتر می‌شود و پیشروی می‌کند.\nفَحِیلَ بَیْنَ أَحَدِهِمْ وَ بَیْنَ مَنْطِقِهِ\nپس میان انسان و زبانش یک فاصله [حِیلَ] ایجاد می‌شود. اولین عارضه آن، ازکارافتادن زبان است که به وقوع می‌پیوندد.\nاهل معرفت گویند لحظه‌ای است که انسان باطن امور را می‌بیند؛ اگر انسان گنهکار باشد فرشته‌های عذاب و اگر انسان خوب باشد فرشته‌های نعمت را هم می‌بیند. ولی چون نباید اسرار را فاش کند، اولین عضو، زبان، قفل می‌شود و دلیل این نباید، این است که دیگران از روی ترس و اجبار اطاعت خدا را نکنند.\nوَ یَسْمَعُ بِأُذُنِهِ عَلَی صِحَّةٍ مِنْ عَقْلِهِ وَ بَقَاءٍ مِنْ لُبِّهِ\nزبان لال است، ولی گوش همه صداها را می‌شنود و شخصی که در طول زندگی تمام عقل خود را بابت خوشی‌های دنیوی صرف کرده بود، در لحظه انتظار، عقل را خوب و عالی درمی‌یابد، درحالی‌که تبدیل به عقل خالص [لُبّ] شده که هیچ خدشه‌ای در آن نیست.\nچون عقل به دیدن حقایق عالم و اعتقاد به معاد است. دانشمندترین افراد اگر خداپرست نباشند، عاقل نیستند.\nیُفَکِّرُ فِیمَ أَفْنَی عُمُرَهُ وَ فِیمَ أَذْهَبَ دَهْرَهُ\nدرحالی‌که عقل کامل دارد، شروع به فکرکردن می‌کند؛ فکری که در طول عمر باید به کار می‌انداخت، در احتضار به کار می‌اندازد که عمر خود را در چه راهی به فنا گذرانده است.\nحدیث نبوی:\n«مُوتُوا قَبْلَ أَنْ تَمُوتُوا» اشاره به همین مطلب است که حقیقت مرگ، فکر درباره عمر است.\nسرمایه عمر را کجا خرج کند مهم است.\nیَتَذَکَّرُ أَمْوَالاً جَمَعَهَا أَغْمَضَ فِی مَطَالِبِهَا وَ أَخَذَهَا مِنْ مُصَرَّحَاتِهَا وَ مُشْتَبِهَاتِهَا\nبا خود فکر می‌کند اموالی که طول عمر جمع کرده حلال بوده یا حرام. او به یاد می‌آورد که در طلب این اموال چشم خود را بسته [أَغْمَضَ] بود و به حلال و حرام بودن توجهی نداشت. با آنکه می‌دانست پول حرام یا شبهه‌ناک است، آن را اخذ می‌کرد و فقط به جمع‌کردن فکر می‌کرد.\nحدیث از امام کاظم علیه‌السلام:\n«لَیْسَ مِنَّا مَنْ لَمْ یُحَاسِبْ نَفْسَهُ فِی کُلِّ یَوْمٍ فَإِنْ عَمِلَ حَسَناً اسْتَزَادَ اللَّهَ وَ إِنْ عَمِلَ سَیِّئاً اسْتَغْفَرَ اللَّهَ مِنْهُ وَ تَابَ إِلَیْهِ»\nاز ما نیست کسی که نفس خود را هر روز محاسبه نکند؛ به عمل صالح انجام داده و عمل سیئه استغفار و توبه نماید.\nقَدْ لَزِمَتْهُ تَبِعَاتُ جَمْعِهَا تَبِعَاتُ جَمْعِهَا\nدر برزخ، تمامی حق‌الناس به او چسبیده [قَدْ لَزِمَتْهُ]\nوَ أَشْرَفَ عَلَی فِرَاقِهَا تَبْقَی لِمَنْ وَرَاءَهُ [یُنَعَّمُونَ] یَنْعَمُونَ فِیهَا وَ یَتَمَتَّعُونَ بِهَا\nدچار فراق اندوخته‌هایی می‌شود که در پشت سر جا گذاشته، درحالی‌که دیگران از پول او استفاده می‌کنند و از آن بهره می‌برند [یَتَمَتَّعُونَ]\nفَیَکُونُ الْمَهْنَأُ لِغَیْرِهِ وَ الْعِبْءُ عَلَی ظَهْرِهِ\nدر لحظه احتضار متوجه می‌شود خوشی و آسودگی [الْمَهْنَأُ] اموال برای دیگران می‌ماند و بار سنگین پاسخگویی و عذاب به دوش [ظَهْرِهِ] خود اوست.\nوَ الْمَرْءُ قَدْ غَلِقَتْ رُهُونُهُ بِهَا\nمحتضر در گرو اعمال خود که انجام داده قفل شده است [غَلِقَتْ]\nفَهُوَ یَعَضُّ یَدَهُ نَدَامَةً عَلَی مَا أَصْحَرَ لَهُ عِنْدَ الْمَوْتِ مِنْ أَمْرِهِ\nدر آن لحظه انسان دست خود را از روی ندامت و پشیمانی با آشکارشدن [أَصْحَرَ] بسیاری از حقایق گاز می‌گیرد [یَعَضُّ]\nاین دست گازگرفتن می‌تواند حقیقت باشد (که جسم متناسب آن دنیا معاد جسمانی و روحانی دارد این کار را انجام می‌دهد) یا معنای کنایی از حسرت است.\nهنوز مرگ حاصل نشده؛ چشم می‌گردد و گوش می‌شنود.\nوَ یَزْهَدُ فِیمَا کَانَ یَرْغَبُ فِیهِ أَیَّامَ عُمُرِهِ\nخواه‌ناخواه در نهایت آن لحظه، خاضع، زاهد، تسلیم می‌شود و تمام اموری که تلاش می‌کرد به آن‌ها برسد برایش بی‌ارزش می‌شوند.\nوَ یَتَمَنَّی أَنَّ الَّذِی کَانَ یَغْبِطُهُ بِهَا وَ یَحْسُدُهُ عَلَیْهَا قَدْ حَازَهَا دُونَهُ.\nمحتضر آرزو می‌کند [یَتَمَنَّی] ای‌کاش همان‌هایی که در دنیا حسادت ایشان را می‌کرد و رقیب او بودند، همه اموالش را برده بودند [یَغْبِطُهُ] و او این مقدار زیاد تلاش برای به‌دست‌آوردن صرف نمی‌کرد و کاش دیگران جمع‌آوری می‌کردند و به او چیزی نمی‌رسید و در مسابقه دنیا آخرین نفر بود.\nفَلَمْ یَزَلِ الْمَوْتُ یُبَالِغُ فِی جَسَدِهِ حَتَّی خَالَطَ لِسَانُهُ سَمْعَهُ\nمرگ همچنان پیش می‌رود تا آنکه گوش هم به زبان می‌پیوندد. [خَالَطَ]\nعلامه مجلسی می‌فرماید اینکه مرگ از پا شروع و پیشروی می‌کند تا مغز و قلب و فکر، یکی از نعمت‌های بزرگ خدا است و تا آخرین لحظات فرصت گفتن لا إِلَهَ إِلَّا اللَّهُ را دارد؛ اگرچه در هنگامی که چشم برزخی یافت توبه مقبول نیست، ولی گفتن ذکر برایش ثواب دارد.\nفَصَارَ بَیْنَ أَهْلِهِ لَا یَنْطِقُ بِلِسَانِهِ وَ لَا یَسْمَعُ بِسَمْعِهِ\nتا اینکه بین محتضر و خانواده، نه می‌تواند صحبت کند و نه می‌شنود.\nیُرَدِّدُ طَرْفَهُ بِالنَّظَرِ فِی وُجُوهِهِمْ یَرَی حَرَکَاتِ أَلْسِنَتِهِمْ وَ لَا یَسْمَعُ رَجْعَ کَلَامِهِمْ\nمدام چشم را می‌چرخاند [یُرَدِّدُ]\nحرکات زبان اطرافیان را می‌بیند؛ ولی طنین [رَجْعَ] کلام آن‌ها را نمی‌شنود.\nثُمَّ ازْدَادَ الْمَوْتُ الْتِیَاطاً بِهِ [فَقَبَضَ بَصَرَهُ کَمَا قَبَضَ سَمْعَهُ] فَقُبِضَ بَصَرُهُ کَمَا قُبِضَ سَمْعُهُ وَ خَرَجَتِ الرُّوحُ مِنْ جَسَدِهِ\nسپس این مرگ مانند شکارچی ماهر که بر شکار مسلط شده چنگال‌هایش را بیشتر در وجود انسان فرومی‌برد که هیچ راه فراری آزادانه وجود نداشته باشد. همان‌طور که گوش از کار افتاد چشم از کار می‌افتد و روح کامل از وجود انسان خارج می‌شود.\nفَصَارَ جِیفَةً بَیْنَ أَهْلِهِ قَدْ [أُوحِشُوا] أَوْحَشُوا مِنْ جَانِبِهِ وَ تَبَاعَدُوا مِنْ قُرْبِهِ\nانسانی که تا دیروز شریف و محترم بود تبدیل به مردار و جسم متعفن [جِیفَةً] می‌شود.\nحقیقت وجود انسان روح اوست که اگر گرفته شود تبدیل به مردار می‌شود. اگر همهٔ همت انسان جسم باشد طبق آیه ۱۷۹ اعراف از حیوان پایین‌تر می‌شود. «أُولَئِکَ کَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ أُولَئِکَ هُمُ الْغَافِلُونَ» مانند حیوانات بلکه گمراه‌ترند؛ آن‌ها غفلت زدگان هستند.\nاطرافیان وحشت دارند کنار او بمانند؛ هر کدام آرام‌آرام از او دوری می‌کنند.\nلَا یُسْعِدُ بَاکِیاً وَ لَا یُجِیبُ دَاعِیاً\nروح او می‌بیند حسرت دارد، چرا نمی‌تواند اطرافیان گریان [بَاکِیاً] را یاری نماید و نمی‌تواند جواب آن‌ها را بدهد.\nتمام قوا را به او دادند؛ اما از نوع دنیایی نیست و امکان ارتباط با افراد دنیا را ندارد.\nثُمَّ حَمَلُوهُ إِلَی مَخَطٍّ فِی الْأَرْضِ فَأَسْلَمُوهُ فِیهِ إِلَی عَمَلِهِ وَ انْقَطَعُوا عَنْ زَوْرَتِهِ.\nسپس آرام‌آرام او را تجهیز کرده تا به‌سوی گودال قبر [مَخَطّ] روانه کنند و او را تسلیم عمل خود می‌کنند\n(حضرت نمی‌فرمایند خاک‌سپاری بلکه می‌فرمایند شخص به عملش سپرده می‌شود)\nو اقوام و دوستان برای همیشه از اینکه به زیارت میت برسند دل می‌برند. می‌دانند هیچ‌گاه به این دنیا بازمی‌گردد.\nنکته: قبض روح توسط چه کسی انجام می‌شود؟\nطبق آیات قرآن سه بخش می‌شود\n۱- شخصاً توسط خدا. سوره زمر آیه ۴۲\n«اللَّهُ یَتَوَفَّی الْأَنْفُسَ حِینَ مَوْتِهَا»\n۲- توسط ملک‌الموت. سوره سجده آیه ۱۱\n«قُلْ یَتَوَفَّاکُمْ مَلَکُ الْمَوْتِ الَّذِی وُکِّلَ بِکُمْ ثُمَّ إِلَی رَبِّکُمْ تُرْجَعُونَ»\n۳- توسط ملائک که بر اساس مقام و منزلت انسان ملک مهربان (هر چه مقام منزلت انسان بالاتر) یا ملائکه غلاظ که مأمور عذاب گنهکاران هستند. سوره انعام آیه ۶۱\n«…حَتَّی إِذَا جَاءَ أَحَدَکُمُ الْمَوْتُ تَوَفَّتْهُ رُسُلُنَا وَ هُمْ لَا یُفَرِّطُونَ.»\nحضرت علی علیه‌السلام فرمودند که هرکس بمیرد، مؤمن یا منافق، مرا می‌بیند. ولی مؤمنین وجه رحمانی و چهره زیبای مرا می‌بینند. منافق و دشمن و ناصبی، علی را با چهره غضب‌آلود می‌بینند.\nطبق روایت نبوی توبه تا قبل از زمان رسیدن جان به گلو مقبول است؛ ولی در این لحظه دیگر قبول نیست.\nعلت آن است که توبه وقتی مقبول است که از روی اختیار باشد؛ ولی آن لحظه از روی اجبار است؛ لذا پذیرفته نیست گرچه ثواب دارد.\nغَفَرَ اللَّهُ لِی وَ لَکُمْ\nالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِینَ","بخش چهارم\nمتن:\nثُمَّ حَمَلُوهُ إِلَى مَخَطٍّ فِي الْأَرْضِ، فَأَسْلَمُوهُ فِيهِ إِلَى عَمَلِهِ وَ انْقَطَعُوا عَنْ زَوْرَتِهِ.\nالقيامة:\nحَتَّى إِذَا بَلَغَ الْكِتَابُ أَجَلَهُ وَ الْأَمْرُ مَقَادِيرَهُ وَ أُلْحِقَ آخِرُ الْخَلْقِ بِأَوَّلِهِ، وَ جَاءَ مِنْ أَمْرِ اللَّهِ مَا يُرِيدُهُ مِنْ تَجْدِيدِ خَلْقِهِ، أَمَادَ السَّمَاءَ وَ فَطَرَهَا وَ أَرَجَّ الْأَرْضَ وَ أَرْجَفَهَا وَ قَلَعَ جِبَالَهَا وَ نَسَفَهَا وَ دَكَّ بَعْضُهَا بَعْضاً مِنْ هَيْبَةِ جَلَالَتِهِ وَ مَخُوفِ سَطْوَتِهِ، وَ أَخْرَجَ مَنْ فِيهَا فَجَدَّدَهُمْ بَعْدَ إِخْلَاقِهِمْ وَ جَمَعَهُمْ بَعْدَ تَفَرُّقِهِمْ؛ ثُمَّ مَيَّزَهُمْ لِمَا يُرِيدُهُ مِنْ مَسْأَلَتِهِمْ عَنْ خَفَايَا الْأَعْمَالِ وَ خَبَايَا الْأَفْعَالِ، وَ جَعَلَهُمْ فَرِيقَيْنِ: أَنْعَمَ عَلَى هَؤُلَاءِ وَ انْتَقَمَ مِنْ هَؤُلَاءِ؛ فَأَمَّا أَهْلُ الطَّاعَةِ فَأَثَابَهُمْ بِجِوَارِهِ وَ خَلَّدَهُمْ فِي دَارِهِ، حَيْثُ لَا يَظْعَنُ النُّزَّالُ وَ لَا تَتَغَيَّرُ بِهِمُ‏ الْحَالُ وَ لَا تَنُوبُهُمُ الْأَفْزَاعُ وَ لَا تَنَالُهُمُ الْأَسْقَامُ وَ لَا تَعْرِضُ لَهُمُ الْأَخْطَارُ وَ لَا تُشْخِصُهُمُ الْأَسْفَارُ؛ وَ أَمَّا أَهْلُ الْمَعْصِيَةِ فَأَنْزَلَهُمْ شَرَّ دَارٍ وَ غَلَّ الْأَيْدِيَ إِلَى الْأَعْنَاقِ وَ قَرَنَ النَّوَاصِيَ بِالْأَقْدَامِ وَ أَلْبَسَهُمْ سَرَابِيلَ الْقَطِرَانِ وَ مُقَطَّعَاتِ النِّيرَانِ، فِي عَذَابٍ قَدِ اشْتَدَّ حَرُّهُ وَ بَابٍ قَدْ أُطْبِقَ عَلَى أَهْلِهِ فِي نَارٍ لَهَا كَلَبٌ وَ لَجَبٌ وَ لَهَبٌ سَاطِعٌ وَ قَصِيفٌ هَائِلٌ، لَا يَظْعَنُ مُقِيمُهَا وَ لَا يُفَادَى أَسِيرُهَا وَ لَا تُفْصَمُ كُبُولُهَا، لَا مُدَّةَ لِلدَّارِ فَتَفْنَى وَ لَا أَجَلَ لِلْقَوْمِ فَيُقْضَى.\nو منها في ذكر النبي (ص‏لی الله علیه وآله):\nزُهد النبي:‏\nقَدْ حَقَّرَ الدُّنْيَا وَ صَغَّرَهَا وَ أَهْوَنَ بِهَا وَ هَوَّنَهَا وَ عَلِمَ أَنَّ اللَّهَ زَوَاهَا عَنْهُ اخْتِيَاراً وَ بَسَطَهَا لِغَيْرِهِ احْتِقَاراً فَأَعْرَضَ عَنِ الدُّنْيَا بِقَلْبِهِ وَ أَمَاتَ ذِكْرَهَا [مِنْ‏] عَنْ نَفْسِهِ وَ أَحَبَّ أَنْ تَغِيبَ زِينَتُهَا عَنْ عَيْنِهِ لِكَيْلَا يَتَّخِذَ مِنْهَا رِيَاشاً أَوْ يَرْجُوَ فِيهَا مَقَاماً بَلَّغَ عَنْ رَبِّهِ مُعْذِراً وَ نَصَحَ لِأُمَّتِهِ مُنْذِراً وَ دَعَا إِلَى الْجَنَّةِ مُبَشِّراً وَ خَوَّفَ مِنَ النَّارِ مُحَذِّراً.\nأهل البيت‏:\nنَحْنُ شَجَرَةُ النُّبُوَّةِ وَ مَحَطُّ الرِّسَالَةِ وَ مُخْتَلَفُ الْمَلَائِكَةِ وَ مَعَادِنُ الْعِلْمِ وَ يَنَابِيعُ الْحُكْمِ، نَاصِرُنَا وَ مُحِبُّنَا يَنْتَظِرُ الرَّحْمَةَ، وَ عَدُوُّنَا وَ مُبْغِضُنَا يَنْتَظِرُ السَّطْوَة.\nترجمه:\nسرانجام او را به سوى گودالى در درون زمين حمل مى کنند; او را به دست عملش مى سپارند و براى هميشه از ديدارش چشم مى پوشند! \nاين وضع (مرگ و ميرهاى آدمى) همچنان ادامه مى يابد تا عمر جهان پايان گيرد و مقدّرات به انتها رسد، و آخرين مخلوقات به نخستين آنها ملحق گردد (و همه بميرند) و فرمان خدا براى بازگشت مخلوقات که اراده کرده است صادر گردد. در اين هنگام آسمان (کرات آسمانى) را به حرکت درمى آورد و از هم مى شکافد; زمين را به لرزه در آورده و به سختى تکان مى دهد; کوهها را از جا کنده، به هر سو پرتاب مى کند و آنها از هيبت جلال و خوف سَطْوَتش به يکديگر کوبيده شده، متلاشى مى گردند. (بعد از اين انقلاب هاى عظيم) خداوند تمام کسانى را که در دل خاک آرميده اند، بيرون مى آورد و پس از فرسودگى، نوسازى مى کند، و بعد از پراکندگى آنها را جمع مى نمايد; سپس آنها را براى سؤال ازاعمال مخفى و افعال پنهانى از هم جدا ساخته، به دو گروه تقسيم مى کند: به اين گروه (نيکان و پاکان) نعمت مى بخشد و آن گروه (بدان) را مجازات مى کند.\nاما اطاعت کنندگان را در جوار رحمت خويش پاداش عطا مى کند، و در سراى جاودانى خود براى هميشه جاى مى دهد. در سرايى که اقامت کنندگانش هرگز از آن کوچ نمى کنند. و حالاتشان دگرگون نمى شود. ترس و وحشتى به آنان روى نمى آورد، و بيمارى به وجودشان عارض نمى شود، خطرى به آنها متوجّه نمى گردد، و سفرها آنها را از ديار خود بيرون نمى راند. \nو اما گناهکاران را در بدترين منزلگاه جاى مى دهد و دست آنها را با غل و زنجير به گردنشان مى بندد، آن گونه که سرهايشان را به پاها نزديک مى کند. لباسى از موادّ آتش زا و جامه هايى از قطعه هاى آتش بر آنها مى پوشاند. در عذابى که حرارتش بسيار شديد و درش به روى آنها بسته است! آتشى پرهيجان که مى خروشد و زبانه مى کشد! شعله هايش فروزان، و صدايش هراس انگيز است. هميشه در آن اقامت دارند و براى آزادى اسيرانش غرامتى پذيرفته نمى شود، و زنجيرهايش گسسته نمى گردد! مدتى براى آن سرا تعيين نشده تا پايان گيرد و سرآمدى براى آن قوم وجود ندارد، تا به آخر رسد!\nپيامبر اسلام(صلى الله عليه وآله) دنيا را بسيار حقير و کوچک مى شمرد و آن را خوار و بى مقدار مى دانست، و در ديدگاه ديگران نيز تحقيرش مى نمود، او مى دانست خداوند براى احترام و گرامى داشت وى، دنيا را از او گرفته و به خاطر حقارتش آن را براى ديگران گسترده ساخته است! (و به اين ترتيب، پيغمبر اکرم(صلى الله عليه وآله)) با قلب و روح خود از دنيا روى گردان شد و ياد آن را براى هميشه در دل خود ميراند، و دوست مى داشت که زينت هاى آن از پيش چشمش پنهان و دور شود، تا از آن لباس فاخرى تهيّه نکند، و يا اقامت در آن را آرزو ننمايد. او در تبليغ احکام الهى به بندگان براى قطع عذر و اتمام حجّت اصرار ورزيد، و امّت خويش را از عذاب خدا بيم داد و نصيحت کرده، آنها را به سوى بهشت دعوت نمود و بشارت داد و از آتش دوزخ برحذر داشت.\nما درخت پر بار نبوّت و جايگاه رسالت و محلّ آمد و شد فرشتگان و معادن علم و چشمه سارهاى حکمتيم، ياوران و دوستداران ما در انتظار رحمت حقّند، و دشمنان کينه توز ما بايد در انتظار مجازات باشند.\nتفسیر:\nوصف رستاخیز و زنده شدن دوباره\nحَتَّیٰ إِذَا بَلَغَ الْکتَابُ أَجَلَهُ وَالْأَمْرُ مَقَادِیرَهُ\nدر ادامهٔ بحث مردگان، دو معنا برای [حَتَّیٰ] وجود دارد.\nالف) میت از خانوادهٔ خود جدا شده و او را نمی‌توانند ببینند [تا اینکه] قیامت فرابرسد.\nب) معنای دیگر [حَتَّیٰ] این است که قصهٔ مرگ‌ومیر و جدایی‌ها همچنان هست و ادامه دارد تا اینکه کار دنیا به سرانجام رسیده و عمر دنیا تمام شود و تمام امور به سرانجام خود برسند.\nوَأُلْحِقَ آخِرُ الْخَلْقِ بِأَوَّلِهِ\nتا اینکه آخرین خلق به اولین آن‌ها در برزخ و قیامت ملحق شوند.\nوَجَاءَ مِنْ أَمْرِ اللَّهِ مَا یرِیدُهُ\nو آنچه را که خدا امر کرده است، به آن برسد.\nمِنْ تَجْدِیدِ خَلْقِهِ\nمنظور این است: فرمان خدا صادر می‌شود، آنان که مرده‌اند زنده شوند و عالم خلقت تجدید بشود.\nأَمَادَ السَّمَاءَ وَفَطَرَهَا وَأَرَجَّ الْأَرْضَ وَأَرْجَفَهَا\nیک‌باره آسمان به حرکت نامنظم [أَمَادَ] درمی‌آید و شکافته می‌شود [فَطَرَهَا] و زمین دچار لرزش [أَرَجَّ] و تکان شدید می‌شود [أَرْجَفَهَا].\nوَقَلَعَ جِبَالَهَا وَنَسَفَهَا\nخدای متعال این کوه‌ها را از جای می‌کند [قَلَعَ] و پرتاب می‌کند [نَسَفَهَا]. منظور زلزلهٔ شدیدی است که کل جهان دچار لرزش می‌شود.\nوَدَک بَعْضَهَا بَعْضاً مِنْ هَیبَةِ جَلَالَتِهِ\nبعضی از این کوه‌ها بر بعض دیگر، به‌خاطر هیبت جلال خدا، به هم کوبیده می‌شوند [دَک].\nوقتی شمّه‌ای از این جلال و عظمت نشان داده شود، همهٔ جهان با همهٔ عظمت می‌لرزد.\nوَمَخُوفِ سَطْوَتِهِ\nبه‌خاطر خوفی که از قدرت و غلبهٔ [سَطْوَة] الهی دارند، کوه‌ها به لرزش درمی‌آیند.\nوَأَخْرَجَ مَنْ فِیهَا فَجَدَّدَهُمْ بَعْدَ إِخْلَاقِهِمْ\nبعد از همهٔ اتفاقاتی که می‌افتد، یکی‌یکی امواتی که از صدها قرن و هزاران سال پیش در خاک آرمیده بودند و عملاً چیزی از آن‌ها باقی نمانده بود، دوباره جمع می‌شوند و خدای متعال بعد از آنکه کهنه و پوسیده [إِخْلَاق] شده و جسم آن‌ها متلاشی شده بود، آن‌ها را دوباره پدید می‌آورد.\nاین شروع قیامت است.\nنکته: یکی از ادلهٔ مهم ما در موضوع معاد جسمانی و روحانی، این کلام حضرت است.\nابن سینا معتقد است که باعقل نمی‌توان معاد جسمانی را اثبات نمود؛ اما هنگامی که از روایات و قرآن بهره می‌گیریم، این موضوع اثبات می‌شود، منتها عقل انسان به این موضوع نمی‌رسد.\nوَجَمَعَهُمْ بَعْدَ تَفَرُّقِهِمْ\nبعد از متلاشی‌شدن جسم‌ها و شخم خوردن زمین‌ها، همه جمع‌آوری می‌شوند.\nثُمَّ مَیزَهُمْ لِمَا یرِیدُهُ مِنْ مَسْأَلَتِهِمْ عَنْ خَفَایا الْأَعْمَالِ وَخَبَایا الْأَفْعَالِ\nهمهٔ اتفاقاتی که افتاد، برای این است که تمیز داده شوند [مَیزَهُمْ] و خدای متعال آن‌ها را از اعمال پنهان و افعال پنهان [خَبَایا] بازخواست می‌کند. ظاهر اعمال و باطن اعمال مورد سؤال قرار می‌گیرد.\nتفاوت اعمال و افعال:\nبزرگان، اعمال را به معنای عمل خوب پنهان و افعال را به معنای کارهای حرام در خلوت بیان کرده‌اند.\nنکته: خدای متعال انسان را بابت افعال و اعمال پنهانی و مخفی و نیات انسان، هم مورد سؤال قرار می‌دهد.\nوَجَعَلَهُمْ فَرِیقَینِ\nاز این قسمت به بعد، مردم به دودسته تقسیم می‌شوند. تا اینجا همه با هم بودند.\nأَنْعَمَ عَلَی هَؤُلَاءِ\nگروهی هستند که خدای متعال به آن‌ها نعمت می‌دهد که همان بهشتیان هستند.\nوَانْتَقَمَ مِنْ هَؤُلَاءِ\nگروه دوم کسانی هستند که خدای متعال آن‌ها را مجازات می‌نماید.\nفَأَمَّا أَهْلُ الطَّاعَةِ فَأَثَابَهُمْ بِجِوَارِهِ\nبهشتیان کسانی هستند که ثواب اعمال آن‌ها را همنشینی با خودش قرار می‌دهد. منظور همنشینی با رحمت خدای متعال و اولیای الهی است [بِجِوَارِهِ].\nوَخَلَّدَهُمْ فِی دَارِهِ\nآن‌ها در بهشت، همیشگی و خالد خواهند بود.\nحَیثُ لَا یظْعَنُ النُّزَّالُ\nکسی که وارد بهشت شد، دیگر خارج نمی‌شود. بهشت جایی است که اهل آن از آنجا کوچ نمی‌کنند [لَا یظْعَنُ]. هیچ عامل بیرونی نمی‌تواند انسان را از بهشت خارج کند.\nوَلَا تَتَغَیرُ بِهِمُ الْحَالُ\nحال خوشی که اهل بهشت دارند، هیچ‌گاه بد نمی‌شود. کسل شدن، نگرانی و اضطراب در آن‌ها نیست. حال خوش به‌صورت استمرار و دائمی در اهل بهشت وجود دارد.\nوَلَا تَنُوبُهُمُ الْأَفْزَاعُ\nهیچ ترس و دل‌نگرانی بر اهل بهشت عارض نمی‌شود [لَا تَنُوبُهُمْ].\nوَلَا تَنَالُهُمُ الْأَسْقَامُ وَلَا تَعْرِضُ لَهُمُ الْأَخْطَارُ\nدر بهشت بیماری [أَسْقَام] بر کسی مستولی نمی‌شود. هیچ خوف و خطری بر آن‌ها عارض نمی‌شود.\nوَلَا تُشْخِصُهُمُ الْأَسْفَارُ\nسفرها آن‌ها را تغییر نداده و از جایی به جایی نبرند.\nخود آنان هم میل سفر از بهشت ندارند. در حقیقت هیچ عامل درونی‌ای هم در اهل بهشت نیست که قصد خارج‌شدن از بهشت در آن‌ها به وجود بیاید.\nچون در بهشت سکونی وجود ندارد که کسی دچار کسالت و خستگی شود؛ بلکه در حال ثبوت هستند و مداوماً عرفان و تعالی افراد به‌سوی کمال می‌رود؛ بنابراین هیچ‌گونه کسالت و خستگی به وجود نمی‌آید.\nوَأَمَّا أَهْلُ الْمَعْصِیةِ فَأَنْزَلَهُمْ شَرَّ دَارٍ\nگروه دوم کسانی هستند که خدای متعال آن‌ها را به بدترین مکان، یعنی جهنم، وارد می‌کند.\nوَغَلَّ الْأَیدِی إِلَی الْأَعْنَاقِ\nدستان را به گردن‌هایشان می‌بندند.\nوَقَرَنَ النَّوَاصِی بِالْأَقْدَامِ\nموی جلوی سر انسان را به پایش نزدیک می‌کنند. آن‌ها در دنیا در مقابل خدا سر خم نکردند، ولی در قیامت مجبورند این‌گونه خاضع باشند.\nوَأَلْبَسَهُمْ سَرَابِیلَ الْقَطِرَانِ\nلباسی به آن‌ها می‌پوشانند که مواد اشتعال‌زا [قَطِرَان] دارد.\nوَمُقَطَّعَاتِ النِّیرَانِ\nلباس آنان از جنس آتش است. به عبارتی، لباس قطعه‌ای از آتش است و نشان‌دهندهٔ این است که فرد مدام در حال سوختن است.\nفِی عَذَابٍ قَدِ اشْتَدَّ حَرُّهُ\nعذاب جهنم به صورتی است که گرمای آن [حَرّ] مدام در حال افزایش است.\nوَبَابٍ قَدْ أُطْبِقَ عَلَی أَهْلِهِ\nدرهای جهنم هم به روی اهل آن بسته شده است و کسی نمی‌تواند از آنجا خارج شود.\nفِی نَارٍ لَهَا کلَبٌ وَلَجَبٌ\nآن‌ها در آتشی گرفتار شده‌اند که هار و درنده [کلَب] است. آتش جهنم مثل آتش دنیا نیست و این آتش به دلیل فهمی که دارد، به عده‌ای حمله می‌کند. همچنین این آتش سروصدا [لَجَب] دارد که خود، عذاب مضاعفی است.\nوَلَهَبٌ سَاطِعٌ\nآتش جهنم زبانه‌ای می‌کشد که خدا می‌داند.\nوَقَصِیفٌ هَائِلٌ\nدارای صدای شدید [قَصِیف] است که انسان را به وحشت [هَائِل] می‌اندازد و این صدا خود، عذاب مضاعفی است.\nلَا یظْعَنُ مُقِیمُهَا وَلَا یفَادَی أَسِیرُهَا\nاگر کسی مقیم جهنم شد، کوچ کردن [لَا یظْعَنُ] برای او معنا ندارد و به‌هیچ‌وجه از اهل جهنم، فدیه و پولی [لَا یفَادَی] گرفته نمی‌شود تا از بند جهنم آزاد شوند.\nوَلَا تُفْصَمُ کبُولُهَا\nدر جهنم هیچ امکان شکستن [لَا تُفْصَمُ] غل‌وزنجیر و درب جهنم نیست.\nلَا مُدَّةَ لِلدَّارِ فَتَفْنَی وَلَا أَجَلَ لِلْقَوْمِ فَیقْضَی.\nبرای آن خانه که بدترین خانه‌هاست، تاریخ پایان و انقضایی وجود ندارد [فَیقْضَی]. جهنم همیشگی است و برای اهل جهنم هم مرگی نیست تا عذاب آن‌ها پایان پذیرد. عذاب همیشگی و ابدی است. مرگ در قیامت ذبح می‌شود.\nنکته: خلود در بهشت، قطعی، همگانی و همیشگی است؛ اما برای جهنم، خلود عدهٔ خاصی را شامل می‌شود؛ لذا حضرت می‌فرماید خلود برای کسانی است که مقیم جهنم باشند و اکثر جهنمیان کسانی هستند که بعد از عذاب از جهنم خارج می‌شوند. امکان خروج از جهنم هست. اگر کسی موحّد باشد، در جهنم خالد و جاویدان نمی‌شود. مجموع روایات حاکی از این است که خلود در جهنم برای عدهٔ خاصی است.\nحضرت به‌عنوان اسوه و الگوی زهد و پارسایی از پیامبر اکرم (ص) نام می‌برند.\nفِی ذِکرِ النَّبِی (صَلَّی اللَّهُ عَلَیهِ وَآلِهِ): قَدْ حَقَّرَ الدُّنْیا وَصَغَّرَهَا\nپیامبر اکرم (ص) کسی بود که دنیا در نگاه او حقیر و کوچک بود.\nوَأَهْوَنَ بِهَا وَهَوَّنَهَا\nکوچک شمرد دنیا را، و دنیا را در نگاه دیگران هم کوچک کرد. کلام اهل‌بیت (ع) و پیامبر (ص) بود که دنیا را در نگاه ما هم کوچک کرد.\nوَعَلِمَ أَنَّ اللَّهَ زَوَاهَا عَنْهُ اخْتِیاراً\nپیامبر صلی‌الله علیه و آله چون انتخاب شده بود، می‌دانست که خدا دنیا را از او دورنگه داشته است و دنیا در نگاه او کوچک شد.\nوَبَسَطَهَا لِغَیرِهِ احْتِقَاراً\nخدا دنیا را برای عده‌ای بسط داده است؛ این نشانهٔ حقارت آن‌هاست. [اِحْتِقَار] دنیا ارزش ندارد و برای انسان‌های بی‌ارزش است.\nفَأَعْرَضَ عَنِ الدُّنْیا بِقَلْبِهِ\nپیامبر (ص) کسی بود که از دنیا با قلب خود اعراض و دوری کرد.\nوَأَمَاتَ ذِکرَهَا عَنْ نَفْسِهِ\nذکر و یاد دنیا در وجود پیامبر (ص) مرده بود. ایشان هیچ‌گاه به دنیا توجه نمی‌کرد و دنیا در نگاهش جایی نداشت.\nوَأَحَبَّ أَنْ تَغِیبَ زِینَتُهَا عَنْ عَینِهِ\nپیامبر (ص) دوست داشت که چشمش به زینت‌های دنیا نیفتد.\nلِکیلَا یتَّخِذَ مِنْهَا رِیاشاً\nپیامبر (ص) هیچ‌گاه دوست نداشت چشم به زروزیور [رِیاشاً] دنیا بدوزد. مبادا از زروزیور دنیا برای خود انتخاب کند.\nأَوْ یرْجُوَ فِیهَا مَقَاماً\nپیامبر (ص) اصلاً نگاه به دنیا نمی‌کرد که مبادا بخواهد بیشتر در دنیا اقامت کند. این صفت دنیاطلب‌هاست که در دنیا می‌خواهند بمانند. البته پیامبر (ص) گرفتار نمی‌شد و این‌ها برای ما درس است.\nنکته: تا انسان قلباً از دنیا اعراض نکند، حرفش تأثیرگذار نخواهد بود.\nبَلَّغَ عَنْ رَبِّهِ مُعْذِراً\nراه عذر را بر مردم بست که ای مردم اگر گناه کنید، مجازات می‌شوید.\nوَنَصَحَ لِأُمَّتِهِ مُنْذِراً\nنصیحت کرد برای امت درحالی‌که خیرخواه آنان بود.\nوَدَعَا إِلَی الْجَنَّةِ مُبَشِّراً وَخَوَّفَ مِنَ النَّارِ مُحَذِّراً\nو مردم را دعوت می‌کرد به بهشت درحالی‌که بشارت‌دهنده بود.\nو آن‌ها را از نتیجهٔ کار ترساند درحالی‌که مردم را از جهنم تحذیر می‌کرد.\nنَحْنُ شَجَرَةُ النُّبُوَّةِ\nما هم اهل‌بیت همان پیامبر (ص) و از همان درخت نبوت هستیم.\nوَمَحَطُّ الرِّسَالَةِ\nما محل فرودآمدن رسالت هستیم.\nوَمُخْتَلَفُ الْمَلَائِکةِ\nکسانی هستیم که ملائکه مداوم نزد ما رفت‌وآمد دارند.\nوَمَعَادِنُ الْعِلْمِ وَینَابِیعُ الْحُکمِ\nما اهل‌بیت، معدن علم هستیم.\nچشمه‌های حکمت از ما می‌جوشد.\nنَاصِرُنَا وَمُحِبُّنَا ینْتَظِرُ الرَّحْمَةَ\nکسی که محبّ و ناصر ما باشد، باید انتظار رحمت و نجات داشته باشد.\nوَعَدُوُّنَا وَمُبْغِضُنَا ینْتَظِرُ السَّطْوَةَ.\nکسی که دشمن ما باشد، باید منتظر شدت عقاب باشد.\nنکته: ناصر و محب دو صفت باید با هم باشند. حب و دوستی به‌تنهایی کفایت نمی‌کند؛ بلکه نصرت و یاری‌کننده بودن برای امام مهم است و بلکه از محبت هم مهم‌تر است.\nحتی در بین اهل‌سنت هم محب زیاد است؛ اما ناصر نیست.\nو کسی که محب و ناصر اهل‌بیت (ع) باشد، ان‌شاءالله به رحمت الهی واصل خواهد شد.\nاللَّهُمَّ انْصُرْ نَاصِرِیهِ وَاخْذُلْ خَاذِلِیهِ"]});
